enum VehicleSize { BIKE, CAR, TRUCK }

class Vehicle {
    final String plate; final VehicleSize size;
    Vehicle(String plate, VehicleSize size) { this.plate = plate; this.size = size; }
}

class Spot {
    final String id; final VehicleSize size;
    private boolean occupied;
    Spot(String id, VehicleSize size) { this.id = id; this.size = size; }
    synchronized boolean canFit(Vehicle v) { return !occupied && v.size.ordinal() <= size.ordinal(); }
    synchronized void occupy() { occupied = true; }
    synchronized void vacate() { occupied = false; }
}

interface PricingStrategy { double price(long minutesParked, VehicleSize size); }
class HourlyPricing implements PricingStrategy {
    public double price(long m, VehicleSize s) { return Math.ceil(m / 60.0) * (s == VehicleSize.CAR ? 20 : 10); }
}

class SpotManager {
    private final List<Spot> spots;
    SpotManager(List<Spot> spots) { this.spots = spots; }
    // Single writer for allocation: the only place that mutates Spot state.
    synchronized Optional<Spot> allocate(Vehicle v) {
        for (Spot s : spots) if (s.canFit(v)) { s.occupy(); return Optional.of(s); }
        return Optional.empty();
    }
    synchronized void release(Spot s) { s.vacate(); }
}

class ParkingLot {
    private final SpotManager spots; private final PricingStrategy pricing;
    ParkingLot(SpotManager spots, PricingStrategy pricing) { this.spots = spots; this.pricing = pricing; }
